using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor of Computer Science", Bio = "Expert in algorithms and computational theory with over 20 years of teaching experience. Published extensively on programming language design.", Email = "alovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor of Mathematics", Bio = "Specializes in discrete mathematics and formal logic. Recipient of the Distinguished Teaching Award.", Email = "aturing@university.edu" },
            new() { Id = 3, Name = "Dr. Marie Curie", Title = "Professor of Physics", Bio = "Renowned researcher in nuclear physics and radiation studies. Leads the university's applied physics laboratory.", Email = "mcurie@university.edu" },
            new() { Id = 4, Name = "Dr. Charles Darwin", Title = "Professor of Biology", Bio = "Evolutionary biologist with field research spanning three continents. Authored multiple acclaimed textbooks.", Email = "cdarwin@university.edu" },
            new() { Id = 5, Name = "Dr. Noam Chomsky", Title = "Professor of Linguistics", Bio = "Leading authority on syntax and language theory. Directs the Cognitive Science program.", Email = "nchomsky@university.edu" },
            new() { Id = 6, Name = "Dr. Emmy Noether", Title = "Associate Professor of Mathematics", Bio = "Algebraist focusing on abstract algebra and ring theory. Known for innovative teaching methods.", Email = "enoether@university.edu" },
        };

        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "Biology", Code = "BIO", Description = "Study of living organisms and life processes." },
            new() { Id = 5, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "TTh 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = _instructors[0], IsFeatured = true },
            new() { Id = 3, Code = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, indexing, and transaction processing. Includes a semester-long project building a full database application.", Credits = 3, Schedule = "MWF 1:00–1:50 PM", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = _instructors[0], IsFeatured = false },
            new() { Id = 4, Code = "MATH 150", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "MWF 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = _instructors[1], IsFeatured = true },
            new() { Id = 5, Code = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and eigenvectors. Essential for advanced work in science and engineering.", Credits = 3, Schedule = "TTh 1:00–2:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = _instructors[5], IsFeatured = false },
            new() { Id = 6, Code = "MATH 310", Title = "Probability & Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "MWF 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = _instructors[1], IsFeatured = false },
            new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions. Calculus co-requisite.", Credits = 4, Schedule = "TTh 9:00–10:20 AM", DepartmentId = 3, DepartmentName = "Physics", Instructor = _instructors[2], IsFeatured = true },
            new() { Id = 8, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, circuits, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "MWF 2:00–2:50 PM", DepartmentId = 3, DepartmentName = "Physics", Instructor = _instructors[2], IsFeatured = false },
            new() { Id = 9, Code = "BIO 110", Title = "Principles of Biology", Description = "Cell biology, genetics, evolution, and ecology. Includes laboratory component with hands-on experiments.", Credits = 4, Schedule = "TTh 11:00 AM–12:20 PM", DepartmentId = 4, DepartmentName = "Biology", Instructor = _instructors[3], IsFeatured = false },
            new() { Id = 10, Code = "BIO 240", Title = "Genetics & Evolution", Description = "Mendelian and molecular genetics, population genetics, and evolutionary mechanisms. Prerequisites: BIO 110.", Credits = 3, Schedule = "MWF 10:00–10:50 AM", DepartmentId = 4, DepartmentName = "Biology", Instructor = _instructors[3], IsFeatured = true },
            new() { Id = 11, Code = "ENG 101", Title = "College Writing", Description = "Develop clear, effective writing skills through essays, research papers, and peer workshops.", Credits = 3, Schedule = "MWF 9:00–9:50 AM", DepartmentId = 5, DepartmentName = "English", Instructor = _instructors[4], IsFeatured = false },
            new() { Id = 12, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present day, examining major authors and literary movements.", Credits = 3, Schedule = "TTh 2:30–3:50 PM", DepartmentId = 5, DepartmentName = "English", Instructor = _instructors[4], IsFeatured = false },
        };
    }

    public Task<List<Department>> GetDepartmentsAsync()
        => Task.FromResult(_departments);

    public Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return Task.FromResult(query.ToList());
    }

    public Task<List<Course>> GetFeaturedCoursesAsync()
        => Task.FromResult(_courses.Where(c => c.IsFeatured).ToList());

