@using CourseCatalog.Models

<div class="card h-100 shadow-sm">
    <div class="card-body">
        <span class="badge bg-primary mb-2">@Course.Code</span>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted small">@Course.DepartmentName &middot; @Course.Credits credits</p>
        <p class="card-text">@Truncate(Course.Description, 100)</p>
    </div>
    <div class="card-footer bg-transparent">
        <a href="@($"courses/{Course.Id}")" class="btn btn-outline-primary btn-sm">View Details</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength)
        => text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@using CourseCatalog.Models

<div class="card border-start border-primary border-4 h-100">
    <div class="card-body">
        <span class="badge bg-warning text-dark mb-2">⭐ Featured</span>
        <h5 class="card-title">@Course.Code — @Course.Title</h5>
        <p class="card-text text-muted">@Course.DepartmentName &middot; @Course.Credits credits &middot; @Course.Schedule</p>
        <p class="card-text">@Truncate(Course.Description, 120)</p>
        <a href="@($"courses/{Course.Id}")" class="btn btn-primary btn-sm">Learn More</a>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength)
        => text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@using CourseCatalog.Models

<div class="row g-3 mb-4">
    <div class="col-md-8">
        <div class="input-group">
            <span class="input-group-text">🔍</span>
            <input type="text"
                   class="form-control"
                   placeholder="Search courses by title, code, or description…"
                   value="@SearchTerm"
                   @oninput="OnSearchInput" />
        </div>
    </div>
    <div class="col-md-4">
        <select class="form-select" value="@SelectedDepartmentId" @onchange="OnDepartmentChange">
            <option value="0">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = "";
    [Parameter] public int SelectedDepartmentId { get; set; }
    [Parameter] public List<Department> Departments { get; set; } = new();
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }
    [Parameter] public EventCallback<int> SelectedDepartmentIdChanged { get; set; }

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await SearchTermChanged.InvokeAsync(value);
    }

    private async Task OnDepartmentChange(ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var id))
        {
            await SelectedDepartmentIdChanged.InvokeAsync(id);
        }
    }
}

