@page "/courses"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CatalogService Catalog
@inject NavigationManager Nav

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<CourseFilters SearchTerm="@_searchTerm"
              SearchTermChanged="OnSearchTermChanged"
              SelectedDepartmentId="@_selectedDeptId"
              SelectedDepartmentIdChanged="OnDepartmentChanged"
              Departments="_departments" />

@if (_courses is null)
{
    <p><em>Loading courses…</em></p>
}
else if (_courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted mb-3">Showing @_courses.Count course(s)</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in _courses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

@code {
    private List<Course>? _courses;
    private List<Department> _departments = new();
    private string _searchTerm = "";
    private int _selectedDeptId;

    [SupplyParameterFromQuery(Name = "dept")]
    private int? DeptFromQuery { get; set; }

    protected override async Task OnInitializedAsync()
    {
        _departments = await Catalog.GetDepartmentsAsync();

        if (DeptFromQuery.HasValue)
        {
            _selectedDeptId = DeptFromQuery.Value;
        }

        await LoadCoursesAsync();
    }

    private async Task OnSearchTermChanged(string term)
    {
        _searchTerm = term;
        await LoadCoursesAsync();
    }

    private async Task OnDepartmentChanged(int deptId)
    {
        _selectedDeptId = deptId;
        await LoadCoursesAsync();
    }

    private async Task LoadCoursesAsync()
    {
        _courses = await Catalog.GetCoursesAsync(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _selectedDeptId > 0 ? _selectedDeptId : null);
    }
}

@page "/courses/{Id:int}"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CatalogService Catalog

<PageTitle>@(_course?.Title ?? "Course") — University Course Catalog</PageTitle>

@if (_course is null)
{
    <div class="alert alert-warning">Course not found.</div>
    <a href="courses" class="btn btn-outline-primary">← Back to Courses</a>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Code — @_course.Title</h1>
            <p class="text-muted">@_course.DepartmentName</p>

            <div class="row mb-4">
                <div class="col-auto">
                    <span class="badge bg-primary fs-6">@_course.Credits Credits</span>
                </div>
                <div class="col-auto">
                    <span class="badge bg-secondary fs-6">📅 @_course.Schedule</span>
                </div>
            </div>

            <h4>Description</h4>
            <p class="lead">@_course.Description</p>

            <a href="@($"enroll?courseId={_course.Id}")" class="btn btn-success btn-lg mt-3">Request Enrollment</a>
        </div>

        <div class="col-lg-4 mt-4 mt-lg-0">
            <InstructorBio Instructor="_course.Instructor" />
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? _course;

    protected override async Task OnInitializedAsync()
    {
        _course = await Catalog.GetCourseByIdAsync(Id);
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been received. You will be notified by email once it is processed.</p>
        <hr />
        <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-6">
            <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                    <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g. STU-12345" />
                    <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="courseSelect" class="form-label">Course</label>
                    <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Request</button>
            </EditForm>
        </div>
    </div>
}

@code {
    private EnrollmentRequest _model = new();
    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseTitle = "";

    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        _courses = await Catalog.GetCoursesAsync();

        if (PreselectedCourseId.HasValue)
        {
            _model.CourseId = PreselectedCourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        var success = await Catalog.SubmitEnrollmentRequestAsync(_model);
        if (success)
        {
            _selectedCourseTitle = _courses.FirstOrDefault(c => c.Id == _model.CourseId)?.Title ?? "Unknown";
            _submitted = true;
        }
    }
}

